// English / Hebrew strings. t(key, params) falls back to English, then to the key.
let current = 'en';
export const lang = () => current;
export function setLang(l) { current = l === 'he' ? 'he' : 'en'; document.documentElement.lang = current; document.documentElement.dir = current === 'he' ? 'rtl' : 'ltr'; }

export function t(key, params) {
  const e = D[key];
  let s = e ? (e[current === 'he' ? 1 : 0] ?? e[0]) : key;
  if (params) for (const [k, v] of Object.entries(params)) s = s.replaceAll(`{${k}}`, v);
  return s;
}

